xpath.script:
{
"@context": "https://schema.org",
"@type": "FAQPage",
"mainEntity": [
{
"@type": "Question",
"name": "Is Odoo Community really free?",
"acceptedAnswer": {
"@type": "Answer",
"text": "The software is, under the LGPL. The work of implementing and maintaining it is not. Community trades a licence fee for service cost."
}
},
{
"@type": "Question",
"name": "Does Odoo handle Brazilian fiscal documents?",
"acceptedAnswer": {
"@type": "Answer",
"text": "NF-e, CT-e and MDF-e are issued natively by the community localisation, with taxes calculated inside Odoo. NFS-e depends on the municipality. SPED, ECD and ECF are generated from the accounting data and validated in a specialist tool. Payroll is not solved by any Odoo edition."
}
},
{
"@type": "Question",
"name": "How much does an Odoo implementation cost?",
"acceptedAnswer": {
"@type": "Answer",
"text": "It depends on process complexity, fiscal profile, integrations and data migration rather than primarily on head count. Comparable companies invest around one percent of annual revenue in their management platform."
}
},
{
"@type": "Question",
"name": "Do I get the source code of my Odoo customisations?",
"acceptedAnswer": {
"@type": "Answer",
"text": "Yes, in a repository accessible from the first week of the project, together with the deployment recipe."
}
},
{
"@type": "Question",
"name": "Can Escodoo take over an Odoo somebody else implemented?",
"acceptedAnswer": {
"@type": "Answer",
"text": "Yes. It starts with a fixed scope assessment, either a second opinion or a project rescue depending on the state of the installation."
}
}
]
}
